function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-50, H/2-75, 100, 150);
  ctx.strokeRect(W/2-50, H/2-75, 100, 150);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-125, 25, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2, H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-75);
  ctx.lineTo(W/2-30, H/2-25);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-75);
  ctx.lineTo(W/2+30, H/2-25);
  ctx.stroke();

  // wisdom bubble
  ctx.fillStyle = 'lightblue';
  ctx.beginPath();
  ctx.arc(W/2+80, H/2-150, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1554', W/2+80, H/2-150);

  // life line
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-25);
  ctx.lineTo(W/2, H-25);
  ctx.stroke();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 2;
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2, H/2-25+i*20);
    ctx.lineTo(W/2+20+10*Math.sin(t+i), H/2-25+i*20);
    ctx.stroke();
  }

  ctx.restore();
}
